#!/usr/bin/env python3
"""Write bundled app icons into icons/."""
from pathlib import Path
import base64
ICONS = {
    'favicon.png': """""",
    'apple-touch-icon.png': """""",
    'icon-192.png': """""",
    'icon-512.png': """""",
    'icon-maskable-512.png': """""",
    'icon-32.png': """""",
    'icon-64.png': """""",
    'icon-128.png': """""",
    'icon-180.png': """""",
    'icon-256.png': """""",
    'icon-1024.png': """"""
}
def write(dest=None):
    dest = Path(dest) if dest else Path(__file__).resolve().parent.parent / "icons"
    dest.mkdir(parents=True, exist_ok=True)
    for name, data in ICONS.items():
        (dest / name).write_bytes(base64.b64decode(data))
    return dest
if __name__ == "__main__":
    print(write())
